package com.sobrenaturaldirector.derivation;
import java.util.*; import com.sobrenaturaldirector.observation.model.*;
public final class ObservationDeltaCalculator { public ObservationDelta calculate(ObservationFrame before,ObservationFrame after){Map<UUID,PlayerSnapshot>a=new HashMap<UUID,PlayerSnapshot>();Map<UUID,PlayerSnapshot>b=new HashMap<UUID,PlayerSnapshot>();for(PlayerSnapshot p:before.getPlayers())a.put(p.getPlayerId(),p);for(PlayerSnapshot p:after.getPlayers())b.put(p.getPlayerId(),p);Set<UUID> ids=new TreeSet<UUID>();ids.addAll(a.keySet());ids.addAll(b.keySet());List<PlayerDelta> out=new ArrayList<PlayerDelta>();for(UUID id:ids){PlayerSnapshot x=a.get(id),y=b.get(id);if(x==null){out.add(new PlayerDelta(id,true,false,false,false,false,false,false,false,false,Double.NaN,y.getHealth()));continue;}if(y==null){out.add(new PlayerDelta(id,false,true,false,false,false,false,!x.isAlive(),false,false,x.getHealth(),Double.NaN));continue;}boolean pos=x.getX()!=y.getX()||x.getY()!=y.getY()||x.getZ()!=y.getZ();boolean health=x.getHealth()!=y.getHealth()||x.getMaxHealth()!=y.getMaxHealth();out.add(new PlayerDelta(id,false,false,health,!x.getInventory().equals(y.getInventory()),x.getArmorValue()!=y.getArmorValue(),x.getDimension()!=y.getDimension(),x.isAlive()&&!y.isAlive(),!x.isAlive()&&y.isAlive(),pos,x.getHealth(),y.getHealth()));}return new ObservationDelta(out);} }
